import React, { useState } from 'react';

// === Link Google Fonts (Serif: Playfair Display, Sans: Inter) ===
// Masukkan link ini di file public/index.html di dalam tag <head>, 
// TEPAT DI ATAS tag <title>.
/* <link rel="preconnect" href="https://fonts.googleapis.com">
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link href="https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700&family=Playfair+Display:ital,wght@0,400..900;1,400..900&display=swap" rel="stylesheet">
*/

// Kita definisikan class utility untuk font di sini agar kodenya bersih
const fontSerif = "font-serif tracking-tight"; // Playfair Display
const fontSans = "font-sans tracking-normal"; // Inter

// === Komponen Halaman Profil (Elegant Pastel & Premium Typography) ===
const ProfilePage = ({ data, onBack }) => (
  <div className={`animate-in slide-in-from-right fade-in duration-700 max-w-5xl mx-auto relative z-10 text-left ${fontSans}`}>
    <button onClick={onBack} className="mb-16 flex items-center gap-3 text-slate-400 hover:text-slate-600 transition-all group font-bold tracking-widest text-[11px] uppercase">
      <div className="w-9 h-9 rounded-full border border-slate-200 flex items-center justify-center group-hover:border-purple-400 group-hover:bg-purple-50 transition-all">
        <span className="text-slate-400 group-hover:-translate-x-0.5 transition-transform text-xs">←</span>
      </div>
      Back to Home
    </button>

    {/* Kotak Utama dengan Efek Glassmorphism Pastel */}
    <div className="grid grid-cols-1 md:grid-cols-12 gap-12 bg-white/70 border border-white/50 rounded-[3rem] p-8 md:p-16 backdrop-blur-xl shadow-2xl shadow-purple-100/30 overflow-hidden relative">
      <div className="md:col-span-5 relative">
        <div className={`relative p-1 rounded-[2.8rem] bg-gradient-to-br ${data.warna}`}>
          <div className="rounded-[2.6rem] overflow-hidden aspect-[3/4] bg-slate-50">
            <img src={data.foto} alt={data.nama} className="w-full h-full object-cover" />
          </div>
        </div>
      </div>

      <div className="md:col-span-7 flex flex-col justify-center space-y-8">
        <div>
          <h4 className={`inline-block w-max px-4 py-1.5 rounded-full text-[10px] font-black tracking-[0.2em] uppercase mb-4 bg-white border border-slate-100 shadow-sm ${data.warnaText}`}>
            Student Profile
          </h4>
          {/* NAMA ANGGOTA - FONT SERIF */}
          <h1 className={`text-5xl md:text-6xl font-extrabold text-slate-900 leading-[1.1] ${fontSerif}`}>
            {data.nama}
          </h1>
          <p className={`text-xl font-mono opacity-70 mt-2 ${data.warnaText}`}>{data.nim}</p>
        </div>
        
        <div className="grid grid-cols-1 sm:grid-cols-2 gap-x-8 gap-y-6 pt-8 border-t border-slate-100">
          {[
            { label: 'Class / Group', value: data.kelas },
            { label: 'Study Program', value: data.jurusan },
            { label: 'Current Location', value: data.domisili }
          ].map((item, index) => (
            <div key={index} className="border-l-2 border-slate-100 pl-4 space-y-1">
              <p className="text-[9px] text-slate-400 uppercase font-black tracking-[0.2em]">{item.label}</p>
              <p className="text-base text-slate-700 font-semibold">{item.value}</p>
            </div>
          ))}
        </div>

        <div className="bg-white/50 p-8 rounded-[2rem] border border-white italic shadow-inner relative">
          <p className="text-slate-600 leading-relaxed text-base font-medium whitespace-pre-line relative z-10">
            "{data.tentang}"
          </p>
          <span className={`absolute -left-3 -top-3 text-7xl opacity-20 ${fontSerif} ${data.warnaText}`}>“</span>
        </div>
      </div>
    </div>
  </div>
);

// === Komponen Utama App (Gallery Urut NIM dengan Premium Typography) ===
export default function App() {
  const [currentPage, setCurrentPage] = useState('home');

  // DATA ANGGOTA (Urut NIM dengan Warna Pastel)
  const dataAnggota = [
    {
      id: "anjani-astagina",
      nama: "Anjani Astagina",
      nim: "253140700111035",
      kelas: "T2-A • Group 5",
      jurusan: "Teknologi Informasi",
      domisili: "Malang",
      foto: "/images/anjani.jpeg",
      warna: "from-blue-200 to-cyan-100",
      warnaText: "text-blue-500",
      tentang: "Anjani, silakan isi biografi kamu di sini minimal 100 kata agar memenuhi syarat penilaian tugas project ini..."
    },
    {
      id: "tzurayya-aisyah",
      nama: "Tzurayya Aisyah P.",
      nim: "253140700111037",
      kelas: "T2-A • Group 5",
      jurusan: "Teknologi Informasi",
      domisili: "Depok",
      foto: "/images/tzurayya.jpeg", 
      warna: "from-emerald-200 to-teal-100",
      warnaText: "text-emerald-600",
      tentang: "Tzurayya, silakan isi biografi kamu di sini minimal 100 kata agar memenuhi syarat penilaian tugas project ini..."
    },
    {
      id: "tabina-naila",
      nama: "Tabina Naila Griselda",
      nim: "253140701111031",
      kelas: "T2-A • Group 5",
      jurusan: "Teknologi Informasi",
      domisili: "Jombang",
      foto: "/images/tabina.jpeg",
      warna: "from-purple-200 to-pink-100",
      warnaText: "text-purple-600",
      tentang: "Halo! Saya adalah mahasiswi program studi Teknologi Informasi di Universitas Brawijaya yang memiliki ketertarikan mendalam pada pengembangan perangkat lunak dan desain antarmuka pengguna (UI/UX). Selama menempuh pendidikan di semester ini, saya telah mempelajari berbagai dasar pemrograman seperti ReactJS dan Tailwind CSS yang saya implementasikan langsung dalam mini project ini. \n\nSaya adalah pribadi yang senang bekerja sama dalam tim, mudah beradaptasi dengan lingkungan baru, serta memiliki rasa ingin tahu yang tinggi terhadap perkembangan teknologi masa kini. Melalui project biodata kelompok ini, saya belajar banyak mengenai kolaborasi menggunakan GitHub serta bagaimana mengelola sebuah proyek secara sistematis." 
    }
  ];

  return (
    // Background Off-White Cream yang sangat lembut
    <div className={`min-h-screen bg-[#FDFBF9] p-10 md:p-20 overflow-x-hidden relative ${fontSans}`}>
      {/* Ornamen Background Pastel Blur */}
      <div className="fixed top-0 left-0 w-full h-full pointer-events-none z-0">
        <div className="absolute top-[-5%] left-[-5%] w-[60%] h-[60%] bg-purple-100/50 blur-[130px] rounded-full"></div>
        <div className="absolute bottom-[-5%] right-[-5%] w-[60%] h-[60%] bg-blue-100/50 blur-[130px] rounded-full"></div>
      </div>

      {currentPage === 'home' ? (
        <div className="relative z-10 text-center animate-in fade-in zoom-in duration-700">
          <header className="mb-24 md:mb-32 space-y-2">
            <p className="text-purple-500 font-bold tracking-[0.4em] uppercase text-xs">Vokasi Universitas Brawijaya</p>
            {/* JUDUL UTAMA - FONT SERIF */}
            <h1 className={`text-7xl md:text-9xl font-extrabold text-slate-950 mb-4 leading-none ${fontSerif}`}>
              Group <span className="text-purple-200">Five</span> Biodata
            </h1>
            <p className="text-lg text-slate-500 max-w-lg mx-auto font-medium">A modern showcase of our technology information student profiles.</p>
          </header>
          
          <div className="grid grid-cols-1 md:grid-cols-3 gap-10 md:gap-12 max-w-7xl mx-auto">
            {dataAnggota.map((item) => (
              <div 
                key={item.id} 
                onClick={() => setCurrentPage(item.id)} 
                className="group cursor-pointer bg-white border border-slate-100 hover:border-purple-100 p-8 rounded-[2.5rem] hover:-translate-y-4 transition-all duration-500 shadow-xl shadow-purple-50/50 hover:shadow-2xl hover:shadow-purple-100/70"
              >
                <div className="aspect-[3/4] rounded-3xl overflow-hidden mb-8 relative shadow-inner">
                  <div className={`absolute inset-0 bg-gradient-to-tr ${item.warna} opacity-30 group-hover:opacity-10 transition-opacity`}></div>
                  <img src={item.foto} className="w-full h-full object-cover transition-transform duration-700 group-hover:scale-110" alt={item.nama} />
                </div>
                {/* NAMA DI CARD - FONT SERIF */}
                <h2 className={`text-3xl font-bold text-slate-900 mb-2 leading-tight group-hover:text-purple-700 transition-colors ${fontSerif}`}>
                  {item.nama}
                </h2>
                <p className="text-slate-400 text-sm mb-6 font-mono tracking-tight">{item.nim}</p>
                <span className={`text-[11px] font-black uppercase tracking-widest group-hover:underline ${item.warnaText}`}>Explore Profile →</span>
              </div>
            ))}
          </div>
        </div>
      ) : (
        <ProfilePage data={dataAnggota.find(a => a.id === currentPage)} onBack={() => setCurrentPage('home')} />
      )}
    </div>
  );
}
